def transform(g):
 h,w=len(g),len(g[0]); out=[r[:] for r in g]
 blocks=[]
 for r in range(h-1):
  for c in range(w-1):
   if all(g[y][x]==2 for y,x in ((r,c),(r+1,c),(r,c+1),(r+1,c+1))): blocks.append((r,c))
 used=set()
 for r,c in blocks:
  pts=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]
  if not all(0<=y<h and 0<=x<w and g[y][x] not in (0,2) for y,x in pts): continue
  vals=[g[y][x] for y,x in pts]
  mapped=[vals[2],vals[0],vals[3],vals[1]]
  dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
  for (y,x),v,(dy,dx) in zip(pts,mapped,dirs):
   out[y][x]=v; used.add((y,x))
   yy,xx=y+dy,x+dx
   while 0<=yy<h and 0<=xx<w:
    if g[yy][xx]==0: out[yy][xx]=v
    yy+=dy;xx+=dx
 return out
